import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv3d_kh_kw_forward(torch::Tensor x,
                                    torch::Tensor w,
                                    c10::optional<torch::Tensor> b,
                                    int stride, int padding, int dilation, int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Cooperative tiled direct 3D convolution (kernel size kH x kW x kD, general stride/padding/dilation/groups).
// Designed for the case kD is small (here typically 1) so the "depth" dimension is handled by an
// extra grid dimension while (H, W) receive the tiled cooperative treatment.

template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win, int D,
    int Cout, int Cin_per_group, int Cout_per_group, int groups,
    int kH, int kW, int kD,
    int stride, int padding, int dilation,
    int Hout, int Wout, int Dout,
    int oc_per_block,
    int patchH, int patchW)
{
  constexpr int TILE_OH = 16;
  constexpr int TILE_OW = 16;
  constexpr int Threads = TILE_OH * TILE_OW;
  constexpr int MAX_OC  = 8;
  extern __shared__ unsigned char smem_raw[];
  T* sX = reinterpret_cast<T*>(smem_raw);
  T* sW = reinterpret_cast<T*>(smem_raw + (size_t)patchH * patchW * sizeof(T));
  const int tid = threadIdx.x;
  const int local_oh = tid / TILE_OW;
  const int local_ow = tid % TILE_OW;
  const int n_od = blockIdx.z;
  const int n    = n_od / Dout;
  const int od   = n_od % Dout;
  const int oc_base  = blockIdx.y * oc_per_block;
  const int group    = oc_base / Cout_per_group;
  const int cin_start = group * Cin_per_group;
  const int n_tiles_w  = (Wout + TILE_OW - 1) / TILE_OW;
  const int tile_idx    = blockIdx.x;
  const int tile_oh_idx = tile_idx / n_tiles_w;
  const int tile_ow_idx = tile_idx % n_tiles_w;
  const int oh_base = tile_oh_idx * TILE_OH;
  const int ow_base = tile_ow_idx * TILE_OW;
  const int oh = oh_base + local_oh;
  const int ow = ow_base + local_ow;
  const bool valid_out = (oh < Hout) && (ow < Wout);
  const int64_t sXc = (int64_t)H * Win * D;
  const int64_t sXh = (int64_t)Win * D;
  const int64_t sXw = (int64_t)D;
  const int64_t sYc = (int64_t)Hout * Wout * Dout;
  const int64_t sYh = (int64_t)Wout * Dout;
  const int64_t sYw = (int64_t)Dout;
  const int64_t sWo = (int64_t)Cin_per_group * kH * kW * kD;
  const int64_t sWc = (int64_t)kH * kW * kD;
  const int64_t sWh = (int64_t)kW * kD;
  const int64_t sXn = (int64_t)Cin * H * Win * D;
  const int64_t sYn = (int64_t)Cout * Hout * Wout * Dout;
  const T* Xn = X + (int64_t)n * sXn;
  T* Yn       = Y + (int64_t)n * sYn;
  const int ih0 = oh_base * stride - padding;
  const int iw0 = ow_base * stride - padding;
  const int id_base = od * stride - padding;
  float acc[MAX_OC];
  #pragma unroll
  for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
    int oc = oc_base + oc_l;
    float bval = 0.0f;
    if (oc_l < oc_per_block && oc < Cout && Bias != nullptr) bval = (float)Bias[oc];
    acc[oc_l] = bval;
  }
  const int patchSize  = patchH * patchW;
  const int weightSize = MAX_OC * kH * kW;
  for (int cin_off = 0; cin_off < Cin_per_group; ++cin_off) {
    int cin = cin_start + cin_off;
    for (int kd_i = 0; kd_i < kD; ++kd_i) {
      int id = id_base + kd_i * dilation;
      bool id_valid = ((unsigned)id < (unsigned)D);
      for (int idx = tid; idx < patchSize; idx += Threads) {
        int ph = idx / patchW;
        int pw = idx - ph * patchW;
        int ih = ih0 + ph;
        int iw = iw0 + pw;
        T val = T(0);
        if (id_valid && (unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
          val = Xn[(int64_t)cin * sXc + (int64_t)ih * sXh + (int64_t)iw * sXw + id];
        }
        sX[idx] = val;
      }
      for (int idx = tid; idx < weightSize; idx += Threads) {
        int oc_l = idx / (kH * kW);
        int kk   = idx - oc_l * (kH * kW);
        int kh_i = kk / kW;
        int kw_i = kk - kh_i * kW;
        T wval = T(0);
        if (oc_l < oc_per_block) {
          int oc = oc_base + oc_l;
          if (oc < Cout) {
            wval = W[(int64_t)oc * sWo + (int64_t)cin_off * sWc + (int64_t)kh_i * sWh + (int64_t)kw_i * kD + kd_i];
          }
        }
        sW[idx] = wval;
      }
      __syncthreads();
      if (valid_out) {
        for (int kh_i = 0; kh_i < kH; ++kh_i) {
          int ph = local_oh * stride + kh_i * dilation;
          const T* sX_row = sX + ph * patchW;
          for (int kw_i = 0; kw_i < kW; ++kw_i) {
            int pw = local_ow * stride + kw_i * dilation;
            float xval = (float)sX_row[pw];
            #pragma unroll
            for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
              if (oc_l >= oc_per_block) break;
              float wval = (float)sW[oc_l * kH * kW + kh_i * kW + kw_i];
              acc[oc_l] += xval * wval;
            }
          }
        }
      }
      __syncthreads();
    }
  }
  if (valid_out) {
    #pragma unroll
    for (int oc_l = 0; oc_l < MAX_OC; ++oc_l) {
      if (oc_l >= oc_per_block) break;
      int oc = oc_base + oc_l;
      if (oc >= Cout) continue;
      Yn[(int64_t)oc * sYc + (int64_t)oh * sYh + (int64_t)ow * sYw + od] = static_cast<T>(acc[oc_l]);
    }
  }
}
torch::Tensor conv3d_kh_kw_forward(torch::Tensor x,
                                    torch::Tensor w,
                                    c10::optional<torch::Tensor> b,
                                    int stride, int padding, int dilation, int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 5, "x must be [N, C, H, W, D]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cout, Cin/groups, kH, kW, kD]");
  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);
  int64_t D   = x.size(4);
  int64_t Cout = w.size(0);
  int64_t Cin_per_group = w.size(1);
  int64_t kH = w.size(2);
  int64_t kW = w.size(3);
  int64_t kD = w.size(4);
  TORCH_CHECK(Cin == Cin_per_group * groups, "Cin must equal Cin_per_group * groups");
  TORCH_CHECK(Cout % groups == 0, "Cout must be divisible by groups");
  int64_t Cout_per_group = Cout / groups;
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");
  int64_t Hout = (H + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;
  int64_t Dout = (D + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0 && Dout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout, Dout}, x.options());
  constexpr int MAX_OC  = 8;
  constexpr int TILE_OH = 16;
  constexpr int TILE_OW = 16;
  constexpr int Threads = TILE_OH * TILE_OW;
  int oc_per_block = (int)std::min<int64_t>(Cout_per_group, MAX_OC);
  while (oc_per_block > 1 && (Cout_per_group % oc_per_block) != 0) oc_per_block--;
  int patchH = (int)((TILE_OH - 1) * stride + (kH - 1) * dilation + 1);
  int patchW = (int)((TILE_OW - 1) * stride + (kW - 1) * dilation + 1);
  int n_tiles_h = (int)((Hout + TILE_OH - 1) / TILE_OH);
  int n_tiles_w = (int)((Wout + TILE_OW - 1) / TILE_OW);
  dim3 block(Threads);
  dim3 grid(
      (unsigned)(n_tiles_h * n_tiles_w),
      (unsigned)((Cout + oc_per_block - 1) / oc_per_block),
      (unsigned)(N * Dout)
  );
  size_t shmem_bytes = (size_t)patchH * patchW * sizeof(float) + (size_t)MAX_OC * kH * kW * sizeof(float);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (shmem_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv3d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shmem_bytes);
  }
  conv3d_kernel<float><<<grid, block, shmem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win, (int)D,
      (int)Cout, (int)Cin_per_group, (int)Cout_per_group, (int)groups,
      (int)kH, (int)kW, (int)kD,
      (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout, (int)Dout,
      oc_per_block,
      patchH, patchW
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_khkw1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_kh_kw_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    3D convolution with square (kH x kW) spatial kernel and kernel_size=1 along
    the last ("depth") axis, implemented with a single fused custom CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        assert in_channels % groups == 0
        assert out_channels % groups == 0

        # weight shape matches nn.Conv3d layout: [out_channels, in_channels/groups, kH, kW, kD=1]
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = (self.in_channels // self.groups) * self.kernel_size * self.kernel_size * 1
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_kh_kw_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
            int(self.groups),
        )

